import{_ as a,o as e,c as i,ai as n}from"./chunks/framework.Duywnu3E.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"module2/task2-5.md","filePath":"module2/task2-5.md"}'),t={name:"module2/task2-5.md"};function l(h,s,r,p,o,b){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h2 id="_5-сконфигурируите-ansible-на-сервере-br-srv" tabindex="-1">5. Сконфигурируйте ansible на сервере BR-SRV: <a class="header-anchor" href="#_5-сконфигурируите-ansible-на-сервере-br-srv" aria-label="Permalink to “5. Сконфигурируйте ansible на сервере BR-SRV:”">​</a></h2><p>• Сформируйте файл инвентаря, в инвентарь должны входить HQ-SRV, HQ-CLI, HQ-RTR и BR-RTR</p><p>• Рабочий каталог ansible должен располагаться в /etc/ansible</p><p>• Все указанные машины должны без предупреждений и ошибок отвечать pong на команду ping в ansible посланную с BR-SRV.</p><h2 id="_1-необходимо-установить-пакет-ansible-и-sshpass-выполнить-это-можно-следующеи-командои" tabindex="-1">1. Необходимо установить пакет ansible и sshpass, выполнить это можно следующей командой: <a class="header-anchor" href="#_1-необходимо-установить-пакет-ansible-и-sshpass-выполнить-это-можно-следующеи-командои" aria-label="Permalink to “1. Необходимо установить пакет ansible и sshpass, выполнить это можно следующей командой:”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get update &amp;&amp; apt-get install –y ansible sshpass</span></span></code></pre></div><h2 id="_2-приведем-фаил-инвентаря-ansible-к-следующему-виду-отредактировав-конфигурационныи-фаил-по-пути-etc-ansible-hosts-любым-удобным-текстовым-редактором-например-vim-или-nano" tabindex="-1">2. Приведем файл инвентаря Ansible к следующему виду, отредактировав конфигурационный файл по пути /etc/ansible/hosts любым удобным текстовым редактором, например vim или nano: <a class="header-anchor" href="#_2-приведем-фаил-инвентаря-ansible-к-следующему-виду-отредактировав-конфигурационныи-фаил-по-пути-etc-ansible-hosts-любым-удобным-текстовым-редактором-например-vim-или-nano" aria-label="Permalink to “2. Приведем файл инвентаря Ansible к следующему виду, отредактировав конфигурационный файл по пути /etc/ansible/hosts любым удобным текстовым редактором, например vim или nano:”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>br-rtr ansible_ssh_host=192.168.1.1 ansible_ssh_user=net_admin ansible_ssh_pass=P@ssword</span></span>
<span class="line"><span>hq-rtr ansible_ssh_host=172.16.1.2 ansible_ssh_user=net_admin ansible_ssh_pass=P@ssword</span></span>
<span class="line"><span>hq-srv ansible_ssh_host=192.168.100.2 ansible_ssh_user=sshuser ansible_ssh_pass=P@ssword ansible_ssh_port=2026</span></span>
<span class="line"><span>hq-cli ansible_ssh_host=192.168.200.2 ansible_ssh_user=Administrator@au-team.irpo ansible_ssh_pass=P@ssword</span></span></code></pre></div><h2 id="_2-1-редактируем-фаил-etc-ansible-ansible-cfg-чтобы-отключить-проверку-ключа-хоста-при-подключении-по-ssh" tabindex="-1">2.1 Редактируем файл /etc/ansible/ansible.cfg, чтобы отключить проверку ключа хоста при подключении по SSH: <a class="header-anchor" href="#_2-1-редактируем-фаил-etc-ansible-ansible-cfg-чтобы-отключить-проверку-ключа-хоста-при-подключении-по-ssh" aria-label="Permalink to “2.1 Редактируем файл /etc/ansible/ansible.cfg, чтобы отключить проверку ключа хоста при подключении по SSH:”">​</a></h2><p>Находим строчку &quot;host_key_checking = False&quot; и раскоментируем ёё</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#host_key_checking = False &gt;&gt; host_key_checking = False</span></span></code></pre></div><h2 id="_2-2-как-проверить" tabindex="-1">2.2 Как проверить?: <a class="header-anchor" href="#_2-2-как-проверить" aria-label="Permalink to “2.2 Как проверить?:”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ansible all -m ping</span></span></code></pre></div><p>Если у вас выводит кучу красного текста, необходимо перезапустить ssh на всех машинках котроые указаны в ansible.cfg</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart sshd</span></span></code></pre></div><p>также стоит проверить правильность написание хостов, при пинге будет понятно с каким хостом у вас проблемы, идите дальше только когда на каждые 4 пинга получите в ответ &quot;понг&quot;</p><h3 id="_5-1" tabindex="-1">5.1 <a class="header-anchor" href="#_5-1" aria-label="Permalink to “5.1”">​</a></h3><p>Доп материалы:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://labex.io/ru/tutorials/ansible-ansible-installation-on-ubuntu-67172</span></span></code></pre></div>`,19)])])}const g=a(t,[["render",l]]);export{c as __pageData,g as default};
